def format_daily_card(card_name, interpretation, user_name="Р вЂќРЎР‚РЎС“Р С–"):
    """Р В¤Р С•РЎР‚Р СР В°РЎвЂљР С‘РЎР‚Р С•Р Р†Р В°Р Р…Р С‘Р Вµ Р С”Р В°РЎР‚РЎвЂљРЎвЂ№ Р Т‘Р Р…РЎРЏ Р вЂР вЂўР вЂ” РЎР‚Р В°Р В·Р Т‘Р ВµР В»Р С•Р Р† Р В»РЎР‹Р В±Р Р†Р С‘ Р С‘ Р С”Р В°РЎР‚РЎРЉР ВµРЎР‚РЎвЂ№"""
    result = f"СЂСџРЉвЂ¦ Р вЂ™Р С’Р РЃР С’ Р С™Р С’Р В Р СћР С’ Р вЂќР СњР Р‡, {user_name}! СЂСџРЉвЂ¦\n"
    result += "РІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓ\n\n"
    result += f"РІСљРЃ Р С™Р С’Р В Р СћР С’: {card_name}\n"
    result += f"СЂСџвЂ™В« Р вЂњР вЂєР Р€Р вЂР ВР СњР СњР С›Р вЂў Р вЂ”Р СњР С’Р В§Р вЂўР СњР ВР вЂў:\n{interpretation['short']}\n\n"
    result += "РІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓ\n"
    result += "СЂСџРЉСџ Р РЋР С›Р вЂ™Р вЂўР Сћ Р СћР С’Р В Р С› Р СњР С’ Р РЋР вЂўР вЂњР С›Р вЂќР СњР Р‡ СЂСџРЉСџ\n"
    result += "РІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓРІвЂќРѓ\n\n"
    result += f"{interpretation['advice']}\n\n"
    result += "СЂСџвЂ™В« Р В­РЎвЂљР В° Р С”Р В°РЎР‚РЎвЂљР В° РЎРѓР С•Р С—РЎР‚Р С•Р Р†Р С•Р В¶Р Т‘Р В°Р ВµРЎвЂљ Р Р†Р В°РЎРѓ Р Р†Р ВµРЎРѓРЎРЉ Р Т‘Р ВµР Р…РЎРЉ.\n"
    result += "Р СџРЎР‚Р С‘РЎРѓР В»РЎС“РЎв‚¬Р В°Р в„–РЎвЂљР ВµРЎРѓРЎРЉ Р С” Р ВµРЎвЂ Р С—Р С•РЎРѓР В»Р В°Р Р…Р С‘РЎР‹ Р Р† Р С”Р В»РЎР‹РЎвЂЎР ВµР Р†РЎвЂ№Р Вµ Р СР С•Р СР ВµР Р…РЎвЂљРЎвЂ№!\n"
